CREATE OR REPLACE TRIGGER "portal_display_z_index_same_timestamp_v1" AFTER UPDATE OF "json" ON "public"."processes" FOR EACH ROW WHEN ((("old"."id" = "new"."id") AND ("old"."version" = "new"."version") AND (NOT ("old"."modified_at" IS DISTINCT FROM "new"."modified_at")) AND ("old"."json" IS DISTINCT FROM "new"."json"))) EXECUTE FUNCTION "private"."portal_display_index_same_timestamp_v1"('process');
